INSERT INTO gis_provider_connectors (jurisdiction_id,provider_name,authority_name,provider_type,base_url,auth_mode,status,trust_level) SELECT cj.id,'UN SALB','United Nations SALB / National Geospatial Information Authority','AUTHORITATIVE_REFERENCE','https://salb.un.org/en/data/nga','NONE','Configured','AUTHORITATIVE_REFERENCE' FROM continental_jurisdictions cj WHERE cj.country_code='NG' AND NOT EXISTS (SELECT 1 FROM gis_provider_connectors g WHERE g.provider_name='UN SALB' AND g.jurisdiction_id=cj.id);
INSERT INTO gis_provider_connectors (jurisdiction_id,provider_name,authority_name,provider_type,base_url,auth_mode,status,trust_level) SELECT cj.id,'GRID3 Nigeria','GRID3 / WorldPop','INDEPENDENT_REFERENCE','https://grid3.org/geospatial-data-nigeria','PROVIDER_DEFINED','Configured','INDEPENDENT_REFERENCE' FROM continental_jurisdictions cj WHERE cj.country_code='NG' AND NOT EXISTS (SELECT 1 FROM gis_provider_connectors g WHERE g.provider_name='GRID3 Nigeria' AND g.jurisdiction_id=cj.id);
INSERT INTO gis_provider_datasets (connector_id,dataset_name,endpoint_url,format,boundary_level,expected_feature_count,source_dataset_version,status) SELECT g.id,'Nigeria ADM2 Administrative Boundaries','https://salb.un.org/en/data/nga','GeoJSON/Shapefile','LGA',774,'2024-08-08','Configured' FROM gis_provider_connectors g WHERE g.provider_name='UN SALB' AND NOT EXISTS (SELECT 1 FROM gis_provider_datasets d WHERE d.dataset_name='Nigeria ADM2 Administrative Boundaries');
INSERT INTO gis_provider_datasets (connector_id,dataset_name,endpoint_url,format,boundary_level,expected_feature_count,source_dataset_version,status) SELECT g.id,'GRID3 Nigeria Administrative Boundaries','https://grid3.org/geospatial-data-nigeria','GeoJSON/ArcGIS REST','STATE_LGA',null,'Current','Configured' FROM gis_provider_connectors g WHERE g.provider_name='GRID3 Nigeria' AND NOT EXISTS (SELECT 1 FROM gis_provider_datasets d WHERE d.dataset_name='GRID3 Nigeria Administrative Boundaries');